public class Solution {
    public static long[] parse_nested_parens(String a0) {
        List<Long> depths = new ArrayList<>();
        for (String group : a0.split(" ")) {
            if (!group.isEmpty()) {
                depths.add(parse_paren_group(group));
            }
        }
        return depths.stream().mapToLong(Long::longValue).toArray();
    }

    private static int parse_paren_group(String s) {
        int depth = 0;
        int maxDepth = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                depth += 1;
                maxDepth = Math.max(depth, maxDepth);
            } else {
                depth -= 1;
            }
        }
        return maxDepth;
    }
}

