public class Solution {
    public static double find_zero(long[] a0) {
        double begin = -1.0;
        double end = 1.0;

        while (poly(a0, begin) * poly(a0, end) > 0) {
            begin *= 2.0;
            end *= 2.0;
        }

        while ((end - begin) > 1e-10) {
            double center = (begin + end) / 2.0;
            if (poly(a0, center) * poly(a0, begin) > 0) {
                begin = center;
            } else {
                end = center;
            }
        }

        return begin;
    }

    private static double poly(long[] xs, double x) {
        double result = 0.0;
        for (int i = 0; i < xs.length; i++) {
            result += xs[i] * Math.pow(x, i);
        }
        return result;
    }
}

