            if (thirtyOneDayMonths.contains(month) && (day < 1 || day > 31)) {
                return false;
            }

            List<Integer> thirtyDayMonths = Arrays.asList(4, 6, 9, 11);
            if (thirtyDayMonths.contains(month) && (day < 1 || day > 30)) {
                return false;
            }

            if (month == 2 && (day < 1 || day > 29)) {
                return false;
            }
        } catch (NumberFormatException e) {
            return false;
        }

        return true;
    }
}

