public class Solution {
    public static String intersection(long[] a0, long[] a1) {
        return isIntersectionPresent(a0[0], a0[1], a1[0], a1[1]) ? "YES" : "NO";
    }

    private static boolean isPrime(long num) {
        if (num == 1 || num == 0) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        for (long i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    private static boolean isIntersectionPresent(long l1, long r1, long l2, long r2) {
        long l = Math.max(l1, l2);
        long r = Math.min(r1, r2);
        if (r - l > 0 && isPrime(r - l)) {
            return true;
        }
        return false;
    }
}

