public class Solution {
    public static long[] minPath(long[][] grid, long k) {
        int n = grid.length;
        long val = (long) n * n + 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1L) {
                    List<Long> temp = new ArrayList<>();
                    if (i != 0) {
                        temp.add(grid[i - 1][j]);
                    }

                    if (j != 0) {
                        temp.add(grid[i][j - 1]);
                    }

                    if (i != n - 1) {
                        temp.add(grid[i + 1][j]);
                    }

                    if (j != n - 1) {
                        temp.add(grid[i][j + 1]);
                    }

                    if (!temp.isEmpty()) {
                        val = Math.min(val, Collections.min(temp));
                    }
                }
            }
        }

        List<Long> ans = new ArrayList<>();
        for (long i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans.add(1L);
            } else {
                ans.add(val);
            }
        }

        return ans.stream().mapToLong(Long::longValue).toArray();
    }
}

