        if (n == 0) {
            return new double[]{1};
        }
        List<Double> myTri = new ArrayList<>();
        myTri.add(1.0);
        myTri.add(3.0);
        for (long i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                myTri.add(i / 2.0 + 1);
            } else {
                double last = myTri.get((int)(i - 1));
                double secondLast = myTri.get((int)(i - 2));
                myTri.add(last + secondLast + (i + 3) / 2.0);
            }
        }
        return myTri.stream().mapToDouble(Double::doubleValue).toArray();
    }
}

