public class Solution {
    public static String fix_spaces(String text) {
        StringBuilder new_text = new StringBuilder();
        int i = 0;
        int start = 0, end = 0;
        while (i < text.length()) {
            if (text.charAt(i) == ' ') {
                end++;
            } else {
                if (end - start > 2) {
                    new_text.append("-").append(text.charAt(i));
                } else if (end - start > 0) {
                    new_text.append(new String(new char[end - start]).replace("\0", "_")).append(text.charAt(i));
                } else {
                    new_text.append(text.charAt(i));
                }
                start = end = i + 1;
            }
            i++;
        }
        if (end - start > 2) {
            new_text.append("-");
        } else if (end - start > 0) {
            new_text.append("_");
        }
        return new_text.toString();
    }
}

